const $=id=>document.getElementById(id);
let currentUser=null,readyCallback,mode='login',users=[],resetUser=null,forced=false;
function error(id,message=''){const el=$(id);el.textContent=message;el.hidden=!message;}
async function request(path,data){const response=await fetch(path,{method:data===undefined?'GET':'POST',headers:{'content-type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'操作未完成，请稍后再试');return result;}
function validate(password,confirmation){if(password.length<8||password.length>128||!/[A-Z]/.test(password)||!/[a-z]/.test(password))throw new Error('密码至少 8 位，同时包含大写和小写字母');if(password!==confirmation)throw new Error('两次输入的密码不一致');}
function setMode(value){mode=value;$('auth-login-tab').classList.toggle('selected',mode==='login');$('auth-register-tab').classList.toggle('selected',mode==='register');$('auth-title').textContent=mode==='login'?'欢迎回来，一起想明白':'从今天起，和小直一起学';$('auth-subtitle').textContent=mode==='login'?'登录后，直接和小直聊聊今天的题目。':'创建自己的账号，记住每一次理解和进步。';$('auth-submit').textContent=mode==='login'?'登录，和小直聊聊':'注册，开始学习';$('auth-confirm-label').hidden=mode!=='register';$('auth-confirm').required=mode==='register';$('password-rule').hidden=false;$('auth-password').autocomplete=mode==='login'?'current-password':'new-password';$('auth-password').value='';$('auth-confirm').value='';$('forgot-password').hidden=mode!=='login';$('forgot-help').hidden=true;error('auth-error');}
function openPassword(required){forced=required;$('password-form').reset();error('password-error');$('password-title').textContent=required?'先设置你自己的密码':'修改密码';$('password-intro').textContent=required?'当前是临时密码。修改完成后，就可以和小直开始学习。':'修改后，其他设备上的登录会失效。';$('password-cancel').hidden=required;$('password-logout').hidden=!required;$('password-dialog').showModal();}
async function accepted(user){currentUser=user;$('account-phone').textContent=user.phone;$('account-role').textContent=user.role==='admin'?'管理员':'学习账号';$('admin-open').hidden=user.role!=='admin';if(user.mustChangePassword){openPassword(true);return;}await readyCallback(user);}
async function logout(){await request('/api/auth/logout',{});location.reload();}
export async function startAccount(onReady){
 readyCallback=onReady;
 $('login-dialog').addEventListener('cancel',event=>event.preventDefault());
 $('auth-login-tab').onclick=()=>setMode('login');$('auth-register-tab').onclick=()=>setMode('register');
 $('forgot-password').onclick=()=>{$('forgot-help').hidden=!$('forgot-help').hidden;};
 $('login-form').onsubmit=async event=>{event.preventDefault();error('auth-error');const button=$('auth-submit');button.disabled=true;try{if(mode==='register')validate($('auth-password').value,$('auth-confirm').value);const result=await request('/api/auth/'+mode,{phone:$('auth-phone').value,password:$('auth-password').value});$('login-form').reset();$('login-dialog').close();await accepted(result.user);}catch(e){error('auth-error',e.message);}finally{button.disabled=false;}};
 $('password-dialog').addEventListener('cancel',event=>{if(forced)event.preventDefault();});
 $('password-form').onsubmit=async event=>{event.preventDefault();error('password-error');const button=event.target.querySelector('button');button.disabled=true;try{validate($('new-password').value,$('confirm-password').value);const result=await request('/api/auth/password',{currentPassword:$('current-password').value,password:$('new-password').value});$('password-form').reset();$('password-dialog').close();await accepted(result.user);}catch(e){error('password-error',e.message);}finally{button.disabled=false;}};
 $('password-cancel').onclick=()=>$('password-dialog').close();$('password-logout').onclick=logout;
 $('account-open').onclick=()=>currentUser?$('account-dialog').showModal():$('login-dialog').showModal();$('account-close').onclick=()=>$('account-dialog').close();
 $('change-password').onclick=()=>{$('account-dialog').close();openPassword(false);};$('logout').onclick=logout;
 $('admin-open').onclick=async()=>{$('account-dialog').close();$('admin-dialog').showModal();await refreshUsers();};$('admin-close').onclick=()=>$('admin-dialog').close();$('admin-search').oninput=renderUsers;
 $('reset-close').onclick=()=>$('reset-dialog').close();$('reset-dialog').addEventListener('close',()=>{$('temporary-password').value='';resetUser=null;});
 $('reset-confirm').onclick=async()=>{const button=$('reset-confirm');button.disabled=true;error('reset-error');try{const result=await request('/api/admin/reset-password',{userId:resetUser.id});$('temporary-password').value=result.temporaryPassword;$('reset-result').hidden=false;button.hidden=true;$('reset-close').textContent='完成';$('reset-description').textContent=`${resetUser.phone} 的旧密码和旧登录已失效。请将下面的临时密码发送给用户。`;await refreshUsers();}catch(e){error('reset-error',e.message);}finally{button.disabled=false;}};
 $('copy-temporary').onclick=async()=>{try{await navigator.clipboard.writeText(`知序学习空间：https://chuzhong.jadecircle.cn/\n手机号：${resetUser.phone}\n临时密码：${$('temporary-password').value}\n请登录后设置自己的新密码。`);$('copy-temporary').textContent='已复制，请私下发送';}catch{$('temporary-password').select();$('copy-temporary').textContent='请手动复制上方密码';}};
 const result=await request('/api/auth/me');if(result.user)await accepted(result.user);else $('login-dialog').showModal();
}
async function refreshUsers(){error('admin-error');try{users=(await request('/api/admin/users')).users;renderUsers();}catch(e){error('admin-error',e.message);}}
function renderUsers(){const search=$('admin-search').value.trim();$('admin-users').replaceChildren();for(const user of users.filter(u=>u.phone.includes(search))){const row=document.createElement('div');row.className='admin-user';const text=document.createElement('div'),phone=document.createElement('strong'),status=document.createElement('small');phone.textContent=user.phone;status.textContent=[user.role==='admin'?'管理员':'学习账号',user.mustChangePassword?'待修改临时密码':'正常'].join(' · ');text.append(phone,status);const button=document.createElement('button');button.className='secondary';button.textContent=user.id===currentUser.id?'当前账号':'重置密码';button.disabled=user.id===currentUser.id;button.onclick=()=>{resetUser=user;$('reset-description').textContent=`确认重置 ${user.phone} 的密码？该用户的所有登录将失效，系统会生成新的临时密码。`;$('reset-result').hidden=true;$('reset-confirm').hidden=false;$('reset-close').textContent='取消';$('copy-temporary').textContent='复制手机号和临时密码';error('reset-error');$('reset-dialog').showModal();};row.append(text,button);$('admin-users').append(row);}}
